-- Liliana Study 3 (both routes): participant-facing documents made accurate.
--
-- WHY. Norm, 2026-10-01: "ethically the priority is to be accurate in
-- communication with participants" -- correct the materials now, REB amendment
-- fast-tracked behind them. Checked against what the platform actually does:
--   * The SONA study's on-site consent (2026-09-11) predated the REB-approved
--     ver2: it stated a 10-of-12 minimum in EACH phase with discontinuation. The
--     design enforces Phase 1 only (ac_p1 on_fail 'withdraw'); Phase 2 is
--     'continue' and the final assessment is always offered.
--   * ver2 itself understated Phase 1: falling below 10/12 does not just reduce
--     credit, it ENDS participation after Phase 1 (adherence withdrawal + email);
--     and a midpoint assessment not completed in its 72 h window also ends it
--     (missed-gate rule). Neither form said so.
--   * Sample size: "approximately 150-180" -> "200 to 340" (registered target 340
--     enrolled; recruitment goal 200+ with the paid route).
--   * Deidentification: March 1, 2027, confirmed by Norm (was Nov 1, 2026).
--   * U of T (not UTM course) students; paid route $18/h up to $54 by Interac
--     e-transfer within ~5 business days; payment records; Liliana as contact.
-- The text is Informed Consent Form_revised_ver3.docx (Ethics/amendment, tracked
-- against ver2), accepted. Both routes use the same form: it states each route's
-- compensation explicitly.
--
-- Debriefs: the SONA debrief promised "3 hours of course credit" regardless of
-- what was completed (credit is pro-rated) and named only Norm; the paid one now
-- also says "for the time you took part".
--
-- New rows, then the studies are pointed at them: earlier versions stay on record
-- (participants who consented before today saw those).

DO $$
DECLARE
  v_sona  constant uuid := '958150a9-7821-4daf-8d83-e9325369d91d';
  v_paid  uuid;
  v_form  uuid;
  v_deb   uuid;
BEGIN
  SELECT id INTO v_paid FROM public.studies WHERE parent_study_id = v_sona;
  IF v_paid IS NULL THEN RAISE EXCEPTION 'Liliana Study 3 — Paid not found'; END IF;

  -- Consent, both studies
  INSERT INTO public.study_consent_forms (study_id, html_content) VALUES (v_sona, $consent$<p><strong>Informed Consent Form</strong></p><p>Thank you for your interest in participating in the study.</p><p>You are being invited to participate because you are a University of Toronto student, and your pre-screening responses indicate you may be experiencing moderate symptoms of stress or low mood. To be eligible, participants must score within the moderate range on validated measures of depression (PHQ-8: 10-19) and/or anxiety (GAD-7: 10-14) and must not have a current or recent diagnosis of a cognitive, mood, or substance use disorder. Approximately 200 to 340 students will participate in this study. Please read the following statements associated with the study:</p><p>I agree to participate in a study to examine the impact of brief online interventions on my emotional well-being. I understand that my participation is entirely voluntary: I can leave the study at any time, and this will have no bearing on the compensation I have already earned, nor will it have any other undesirable consequences.</p><p>The following points have been explained to me:</p><ol><li>The purpose of this research is to examine whether brief daily online interventions may improve perceived stress and emotional well-being in university students, and whether giving participants a choice of intervention with or without feedback about their progress leads to better outcomes. Understanding how choice and feedback shape engagement and effectiveness in digital mental health tools may better inform the development of more accessible, low-cost mental health supports for university students and other populations experiencing moderate stress.</li><li>I understand that I will be asked to answer some longer surveys at the start, middle, and end of the study, and to do brief online interventions and reflections (~4 min) each day during the study.</li><li>I understand that I will be exposed to three brief daily interventions during the first 12-day phase of the study, each targeting a different approach to managing stress. At the midpoint of study, I will be randomly assigned to one of the three groups that will determine how I engage with these interventions during second 12-day phase.</li><li>Procedure. In this fully online study, you will be contacted by email over 31 days, and asked to:<ol><li>Complete this consent form, baseline assessment of your wellbeing, intervention preference, and demographics questionnaire (~ 30 minutes).</li><li>For 12 days complete brief online daily interventions and report on your mood, stress, engagement, and enjoyment (~ 4 min per day).</li><li>Complete a midpoint assessment again measuring your wellbeing and report your intervention preferences (~ 20 minutes).</li><li>For an additional 12 days complete brief online daily interventions and report on your mood, stress, engagement, and enjoyment (~ 4 min per day).</li><li>Complete a final wellbeing assessment and receive a debriefing form about the study (~ 25 minutes)</li></ol></li><li>Compensation. If you complete all study elements you will receive 3 hours of course credit. Each daily intervention and check-in link will be provided to you in an email sent each morning. Each of the 3 major assessments (baseline, midpoint, and final) contributes approximately 30, 20, and 25 minutes of credit respectively, for a combined total of ~1.25 hours.  The remaining ~1.75 hours come from completing the daily interventions and check-ins (24 sessions × ~4 minutes each). To receive full credit for Phase 1, you are expected to complete at least 10 out of 12 daily sessions. If you complete fewer than 10 sessions in Phase 1, you will receive credit only for the sessions completed, rounded up to the nearest half hour. There is no minimum session requirement for Phase 2. If you withdraw early, you will receive credit for the portions of the study you completed, rounded up to the nearest half hour. If you are participating through open recruitment (not through SONA), you will be paid $18 per hour (Ontario minimum wage), up to 3 hours ($54) for full participation, pro-rated to the nearest half hour for partial completion. Payment is made by Interac e-transfer to your University of Toronto email address within approximately 5 business days of your completing or withdrawing from the study, so you must be able to receive Interac e-transfers.</li><li>Benefits. The benefits I may expect to receive from this study are: (a) exposure to brief techniques related to adaptive emotion regulation (b) an appreciation of research on emotion and wellbeing, (c) an opportunity to contribute to scientific research, and (d) compensation for your time, either as course credit (SONA participants) or monetary payment (open recruitment participants)</li><li>Risks. The study is considered minimal risk. The activities in this study involve completing questionnaires about mood and participating in brief online well-being exercises. Although these exercises are designed to promote well-being and positive coping strategies, the researchers acknowledge that some participants may experience temporary emotional discomfort when reflecting on their thoughts or feelings. This study is intended for students experiencing moderate symptoms of stress and low mood. It is not a clinical treatment. If you experience feelings of discomfort at any point during the study, you may refrain from answering any question or withdraw from the study at any time before your data are deidentified (anticipated March 1<sup>st</sup>, 2027) without penalty. You will receive compensation for the portion of the study you have completed up to the time of withdrawal. Information about appropriate campus and community mental health resources will be provided throughout the study, including at each daily-check in. By consenting to participate in this study, you do not waive any legal rights you may have.</li><li>Withdrawal / Leaving the Study. Your participation in this study is voluntary. You may withdraw from the study at any time without negative consequences. If you miss a session, you will simply continue with the next scheduled session the following day. Please note that completing at least 10 out of 12 sessions in Phase 1 is required to receive full Phase 1 credit. There is no minimum attendance requirement for Phase 2. If you complete fewer than 10 of the 12 Phase 1 sessions, or do not complete the midpoint assessment within the 3 days it is available, your participation will end at that point, and you will still receive compensation for the portion of the study you completed. You may request that your data be removed from the study up until your data are deidentified (anticipated on March 1<sup>st</sup>, 2027). After this date, your identifying information (such as name and email) will be permanently removed and replaced with a study ID. Once this process is complete, the research team will no longer be able to link your identity to your data. Because your data will no longer be identifiable after March 1<sup>st</sup>, 2027, It will not be possible to withdraw your data beyond this point. If you choose to withdraw before deidentification, you will receive compensation for the portion of the study you have completed. If you do feel any discomfort at any point, please feel free to raise those concerns to the experimenter. If necessary, participation may be discontinued to protect your well-being.</li><li>Confidentiality. All data collected will remain strictly confidential, and I will be referred to only through a unique study ID number. The Research Oversight and Compliance Office - Human Research Ethics Unit (HREU) may also have confidential access to study data for the purpose of ensuring that participant protection procedures are being followed. Only people associated with the study will see my responses. My name will never be recorded. However, to receive daily intervention and check-in links, I will be asked to provide my email address, which is identifying information. If I am participating through open recruitment, my University of Toronto email address will also be used to send my payment by Interac e-transfer; payment records (my email address, the amount and the date paid) are kept separately from my study responses, as required for university financial records. Once the study is complete, or no later than March 1<sup>st</sup>, 2027, all identifying information will be removed from the study. After this point, my data will be fully deidentified, and it will no longer be possible to determine which data belong to me, even if requested.</li><li>Data Storage. Once the study is complete and all the data has been de-identified, we will share the dataset indefinitely on the Open Science Framework (osf.io), which other researchers can access. Once data is posted to the Open Science Framework, we will no longer be able to remove your data if you decide you wish to withdraw consent.</li><li>Contact. The researcher, Liliana Wu (<a href="mailto:liliana.wu@mail.utoronto.ca">liliana.wu@mail.utoronto.ca</a>), will answer any other questions about the research either now or during the course of the experiment. If I have any other questions or concerns, I can address them to the researcher or to principal investigator: Prof. Norman Farb, <a href="mailto:norman.farb@utoronto.ca">norman.farb@utoronto.ca</a> or by phone at 905-828-3959. You may also contact Prof. Norman Farb to request a summary of research results upon study completion. If you have concerns about your rights as a research participant, please contact the Research Oversight and Compliance Office - Human Research Ethics Unit (HREU) by phone at 416-946-3273, or by email at <a href="mailto:ethics.review@utoronto.ca">ethics.review@utoronto.ca</a>.</li><li>Upon completion of my participation, I will receive a full written explanation about the rationale and predictions underlying this experiment. I may also receive a copy of this consent form by saving this page or by emailing a request for the form to the experimenter above.</li></ol><p>Agreement:</p><p>By signing below, I show that I have fully read and understood the process of this study. I understand that:</p><ul><li>I may be randomized to one of three different interventions focused on adaptive emotion regulation skills.</li><li>I am expected to fill out the three major wellbeing assessments at the start, midpoint, and end of the study.</li><li>I am expected to respond to and complete at least 10 out of 12 daily sessions within the first 12-day intervention period, and to complete the midpoint assessment within the 3 days it is available; if I do not, my participation will end after the first 12-day period, and I will be compensated for the portion I completed.</li><li>I understand that this study is intended for individuals who may be experiencing moderate symptoms of stress and low mood, and who do not have any known reasons that would prevent them from safely participating in daily online interventions and reflections on mood and stress.</li><li>If I am participating through open recruitment, I am a current University of Toronto student and I am able to receive payment by Interac e-transfer.</li><li>I also understand that my participation in this study is completely voluntary and I may withdraw my participation at any time before my data is deidentified (anticipated on March 1<sup>st</sup>, 2027) without any negative consequences.</li></ul>$consent$) RETURNING id INTO v_form;
  UPDATE public.studies SET active_consent_form_id = v_form WHERE id = v_sona;
  INSERT INTO public.study_consent_forms (study_id, html_content)
    SELECT v_paid, html_content FROM public.study_consent_forms WHERE id = v_form
  RETURNING id INTO v_form;
  UPDATE public.studies SET active_consent_form_id = v_form WHERE id = v_paid;

  -- Debrief, SONA
  INSERT INTO public.study_debrief_forms (study_id, docx_url, html_content)
  SELECT v_sona, NULL, replace(d.html_content, $o$Please note that you will receive 3 hours of course research participation credit for participating in the study. If you have any further questions about the study, please contact the researcher at <a href="mailto:norman.farb@utoronto.ca">norman.farb@utoronto.ca</a> or (905) 828-3959.$o$, $n$Please note that you will receive course research participation credit for the time you took part in the study (up to 3 hours). If you have any further questions about the study, please contact the researcher, Liliana Wu, at <a href="mailto:liliana.wu@mail.utoronto.ca">liliana.wu@mail.utoronto.ca</a>, or the principal investigator at <a href="mailto:norman.farb@utoronto.ca">norman.farb@utoronto.ca</a> or (905) 828-3959.$n$)
    FROM public.study_debrief_forms d JOIN public.studies s ON s.active_debrief_form_id = d.id
   WHERE s.id = v_sona
  RETURNING id INTO v_deb;
  IF NOT EXISTS (SELECT 1 FROM public.study_debrief_forms WHERE id = v_deb AND html_content LIKE '%for the time you took part%') THEN
    RAISE EXCEPTION 'SONA debrief: sentence not found -- inspect before proceeding';
  END IF;
  UPDATE public.studies SET active_debrief_form_id = v_deb WHERE id = v_sona;

  -- Debrief, paid
  INSERT INTO public.study_debrief_forms (study_id, docx_url, html_content)
  SELECT v_paid, NULL, replace(d.html_content, $o$Please note that you will be paid for your participation at $18 per hour, up to $54, by Interac e-transfer to your University of Toronto email address within approximately 5 business days.$o$, $n$Please note that you will be paid for the time you took part in the study, at $18 per hour (up to $54), by Interac e-transfer to your University of Toronto email address within approximately 5 business days.$n$)
    FROM public.study_debrief_forms d JOIN public.studies s ON s.active_debrief_form_id = d.id
   WHERE s.id = v_paid
  RETURNING id INTO v_deb;
  IF NOT EXISTS (SELECT 1 FROM public.study_debrief_forms WHERE id = v_deb AND html_content LIKE '%for the time you took part%') THEN
    RAISE EXCEPTION 'paid debrief: sentence not found -- inspect before proceeding';
  END IF;
  UPDATE public.studies SET active_debrief_form_id = v_deb WHERE id = v_paid;
END $$;
